//! 📥️ Test-only source admission drives each real stage from the caller's existing finite wallet.
pub use semio_framework_value_control_contract::*;
pub use semio_framework_value_native_decoding::{native_decoding,native_decoding::NativeDecodeControl,native_decoding::OriginalReceivingPrimary};
pub use semio_framework_value_retained_clone::retained_clone;
pub use semio_framework_value_retirement::retirement;
use crate::{retained_clone::RetainedCloneSource,retirement::RetireOwned};
pub use semio_framework_value_testing_effect_bank::{Wallet,WorkLoan,EffectBank};
pub fn capture<T:RetireOwned+Sync,W>(value:T,wallet:&mut W,loan:impl Fn(&W)->RetainedCloneGrant,mut post:impl FnMut(&mut W,RetainedCloneProgress,u128,(usize,usize),RetainedCloneGrant))->RetainedCloneSource<T>{
 let mut owner=RetainedCloneSource::admission_owned(value,());for _ in 0..10000{if owner.phase()=="ready"{break}let g=loan(wallet);let mut actual=None;let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.advance(&mut RetainedAllocationEffect::new(g,1,&mut actual)));assert!(turn.work<=1);let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());if let Some(bytes)=actual{assert_eq!(bytes,p.retained_capacity_bytes)}assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(wallet,p,turn.work,heap,g);turn.result.unwrap();}assert_eq!(owner.phase(),"ready","source fixture failed at its actual demand {:?}",owner.next_demand());let mut output=None;let g=loan(wallet);let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.take_output(&mut output,g));assert!(turn.work<=1);let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(wallet,p,turn.work,heap,g);turn.result.unwrap();assert!(owner.terminal_is_empty());output.expect("paid source output remains in its actual caller slot")
}

struct ConstructionLoan{current:RetainedCloneGrant,issued:bool,accepted:bool,submitted:RetainedCloneProgress}
impl crate::native_decoding::OriginalConstructionRecipient for ConstructionLoan{type Context<'turn,'source>=() where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}fn source_turn<'turn,'source>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}fn grant<'a,'turn,'source>(&mut self,_:&mut (),quote:OriginalConstructionGrant<'a>)->OriginalConstructionGrantComplete<'a>where 'source:'turn{assert!(!self.issued);assert!(crate::retained_clone::retained_clone_grant_admits(self.current,quote.demand()));self.issued=true;quote.complete(Ok(self.current))}fn accept<'a,'turn,'source>(&mut self,_:&mut (),receipt:OriginalConstructionAccept<'a>)->OriginalConstructionAcceptComplete<'a>where 'source:'turn{let g=receipt.grant();let p=receipt.progress();assert!(!self.accepted);assert!(p.fits(g)&&p.fits(self.current));assert!(g.maximum_items<=self.current.maximum_items&&g.maximum_copy_bytes<=self.current.maximum_copy_bytes&&g.maximum_capacity_bytes<=self.current.maximum_capacity_bytes&&g.maximum_release_bytes<=self.current.maximum_release_bytes&&g.maximum_depth<=self.current.maximum_depth);self.accepted=true;let result=self.submitted.checked_add(p).map(|sum|self.submitted=sum);receipt.complete(result)}fn submitted<'turn,'source>(&self,_:&())->RetainedCloneProgress where 'source:'turn{self.submitted}}
struct WorkProducer{maximum:u64}impl crate::native_decoding::OriginalWorkRecipient for WorkProducer{type Context<'turn,'source>=&'turn u128 where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&&'turn u128)->Result<(),ValueError>where 'source:'turn{Ok(())}fn source_turn<'turn,'source>(&self,_:&&'turn u128)->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}fn settle_partial<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,check:crate::OriginalWorkPartialCheck<'reply>)->crate::OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{check.complete(self.validate_context(context))}
 fn recover_partial<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,check:crate::OriginalWorkPartialCheck<'reply>)->crate::OriginalWorkPartialCheckComplete<'reply> where 'source:'turn{check.complete(self.validate_context(context))}
 fn admits<'a,'turn,'source>(&mut self,remaining:&mut &'turn u128,quote:crate::native_decoding::OriginalWorkQuote<'a>,observed:u64,additional:u64)->crate::native_decoding::OriginalWorkQuoteComplete<'a>where 'source:'turn{quote.complete(Ok(observed.checked_add(additional).is_some_and(|n|u128::from(n)<=(**remaining).min(u128::from(self.maximum)))))}}
pub fn receive<T,E:From<crate::ValueError>>(control:&mut crate::NativeDecodeControl<'_>,g:RetainedCloneGrant,mut work_loan:WorkLoan<'_>,apply:impl FnOnce(&mut crate::NativeDecodeControl<'_>)->crate::RetainedWorkOutcome<T,E>)->crate::RetainedWorkOutcome<T,E>{let mut authority=OriginalConstructionAuthority::new(ConstructionLoan{current:g,issued:false,accepted:false,submitted:Default::default()});let mut work_authority=crate::native_decoding::OriginalWorkAuthority::new(WorkProducer{maximum:work_loan.issued_maximum()});let mut remaining=work_loan.original_remaining();let mut work=0;let result=authority.with_loan(&mut (),|construction_loan|work_authority.with_loan(&mut remaining,|native_work_loan|control.with_work_recipient(native_work_loan,|control|control.with_construction_recipient(construction_loan,|control|{let turn=apply(control);work=turn.work;turn.result})))).map_err(E::from).and_then(|result|result.map_err(E::from)).and_then(|result|result);assert!(!work_authority.has_live_actions(),"fixture cannot abandon original pending work");crate::RetainedWorkOutcome{result,work}}


/// 🧵️ Lends a real one-action Work receipt and original allocator marker to one synchronous leaf.
pub fn with_effect<R>(wallet:&Wallet,grant:RetainedCloneGrant,maximum:u64,operation:impl FnOnce(&mut RetainedAllocationEffect<'_>)->R)->(R,Option<usize>){
 use crate::native_decoding::OriginalWorkRecipient;let mut authority=OriginalWorkAuthority::new(WorkProducer{maximum});let mut remaining=wallet.original_work();let result=authority.with_loan(&mut remaining,|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);let mut action=None;let mut proof=None;assert_eq!(work.prepare_for_action(maximum,&mut action).unwrap(),Some(true));let mut receipt=None;work.issue_performed_for_action(action,&mut receipt).unwrap();let mut actual=None;let output={let mut effect=RetainedAllocationEffect::new(grant,maximum,&mut actual,receipt.as_mut().unwrap());operation(&mut effect)};let performed=OriginalWorkSink::observed_work(receipt.as_ref().unwrap());work.claim_performed_for_action(action,&mut receipt).unwrap();if performed==0{work.cancel_for_action(&mut action).unwrap()}else{let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());let partial=partial.take().expect("original fixture Work partial outcome");assert_eq!(partial.total(),performed);assert!(partial.source_refusal().is_none());assert!(work.commit_for_action(performed,action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap()}(output,actual)}).unwrap();assert!(!authority.has_live_actions());result
}
pub fn post_step<E>(wallet:&mut Wallet,turn:crate::RetainedWorkOutcome<crate::RetainedCloneStep,E>,grant:RetainedCloneGrant,heap:(usize,usize),receipt:impl FnOnce(&E)->RetainedCloneProgress)->Result<crate::RetainedCloneStep,E>{let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(receipt);assert!(turn.work<=1);wallet.post(p,turn.work,grant,heap);turn.result}
/// ⛽️ Posts only work covered by the exact original caller loan.
pub fn post_step_with_work<E>(wallet:&mut Wallet,turn:crate::RetainedWorkOutcome<crate::RetainedCloneStep,E>,grant:RetainedCloneGrant,maximum:u64,heap:(usize,usize),receipt:impl FnOnce(&E)->RetainedCloneProgress)->Result<crate::RetainedCloneStep,E>{let p=turn.result.as_ref().map(|step|step.progress()).unwrap_or_else(receipt);assert!(turn.work<=u128::from(maximum));wallet.post(p,turn.work,grant,heap);turn.result}
pub fn denials(g:RetainedCloneGrant,d:crate::RetirementDemand)->impl Iterator<Item=RetainedCloneGrant>{[(true,RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0,RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0,RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}),(d.depth>0,RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().filter_map(|(yes,g)|yes.then_some(g))}
pub fn close_owned<T:RetireOwned>(value:T,wallet:&mut Wallet,body:usize,limit:usize){let(mut owner,h)=semio_framework_value_testing_allocator::observe_retirement_allocations(||crate::retirement::controlled::ControlledRetirement::new(value).unwrap_or_else(|_|panic!("native fixture supports paid original closure")));assert_eq!(h,(0,0));for _ in 0..limit{if owner.terminal_is_empty(){return}let d=owner.next_demand(body).unwrap();assert!(d.copy_bytes<=body);let g=wallet.loan(1,body);let units=owner.next_computational_work(body).unwrap();let mut actual=None;let(result,h)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.step(&mut RetainedAllocationEffect::new(g,units,&mut actual)));let work=owner.last_turn_work();let progress=result.as_ref().map(|step|step.progress()).unwrap_or_else(|failure|failure.retained_progress());if let Some(bytes)=actual{assert_eq!(bytes,progress.retained_capacity_bytes)}post_step(wallet,crate::RetainedWorkOutcome{result,work},g,h,|failure|failure.retained_progress()).unwrap();}panic!("native fixture did not close in its original turn bound")}

